function emptyMetric() {
    return {
        responses: 0,
        lastBytes: 0,
        maxBytes: 0,
        lastSerializationMs: 0,
        maxSerializationMs: 0,
        lastAt: null
    };
}
function roundedMilliseconds(value) {
    return Math.round(Math.max(0, value) * 1_000) / 1_000;
}
/** Serializes once while retaining compact response-size/timing diagnostics. */ export class JsonResponseTracker {
    #metrics;
    #measureNow;
    #wallNow;
    constructor(channels, dependencies = {}){
        this.#metrics = Object.fromEntries(channels.map((channel)=>[
                channel,
                emptyMetric()
            ]));
        this.#measureNow = dependencies.measureNow ?? performance.now.bind(performance);
        this.#wallNow = dependencies.wallNow ?? (()=>new Date());
    }
    response(channel, value, init = {}) {
        const started = this.#measureNow();
        const body = JSON.stringify(value);
        if (body === undefined) {
            throw new TypeError("JSON response value is not serializable");
        }
        const serializationMs = roundedMilliseconds(this.#measureNow() - started);
        const bytes = Buffer.byteLength(body, "utf8");
        const metric = this.#metrics[channel];
        metric.responses++;
        metric.lastBytes = bytes;
        metric.maxBytes = Math.max(metric.maxBytes, bytes);
        metric.lastSerializationMs = serializationMs;
        metric.maxSerializationMs = Math.max(metric.maxSerializationMs, serializationMs);
        metric.lastAt = this.#wallNow().toISOString();
        const headers = new Headers(init.headers);
        if (!headers.has("Content-Type")) {
            headers.set("Content-Type", "application/json; charset=utf-8");
        }
        headers.set("Content-Length", String(bytes));
        return new Response(body, {
            ...init,
            headers
        });
    }
    snapshot() {
        const snapshot = {};
        for (const channel of Object.keys(this.#metrics)){
            snapshot[channel] = {
                ...this.#metrics[channel]
            };
        }
        return snapshot;
    }
}
